package com.smarthub.plus;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;
/** Tests real key dispatch and decoder requests using the installed, user-imported catalogue. */
final class NavigationAcceptance36 {
 private static final java.util.concurrent.atomic.AtomicReference<Activity> top=new java.util.concurrent.atomic.AtomicReference<>();
 private static final Application.ActivityLifecycleCallbacks life=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){top.set(a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
 private static void need(boolean value,String why){if(!value)throw new AssertionError(why);}
 private static Object field(Object o,Class<?> k,String name)throws Exception{Field f=k.getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 private static Activity await(Class<?> k)throws Exception{for(int n=0;n<100;n++){Activity a=top.get();if(k.isInstance(a)&&a.hasWindowFocus())return a;Thread.sleep(100);}throw new AssertionError("Activity did not resume: "+k.getSimpleName());}
 private static void key(Instrumentation t,Activity a,int code){t.runOnMainSync(()->{long now=SystemClock.uptimeMillis();a.dispatchKeyEvent(new KeyEvent(now,now,KeyEvent.ACTION_DOWN,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,KeyEvent.FLAG_FROM_SYSTEM|KeyEvent.FLAG_VIRTUAL_HARD_KEY,InputDevice.SOURCE_KEYBOARD));a.dispatchKeyEvent(new KeyEvent(now,now+10,KeyEvent.ACTION_UP,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,KeyEvent.FLAG_FROM_SYSTEM|KeyEvent.FLAG_VIRTUAL_HARD_KEY,InputDevice.SOURCE_KEYBOARD));});}
 private static boolean playing(Context c,ReceiverCatalog.Channel channel)throws Exception{for(int n=0;n<180;n++){if(SatelliteState.read(c).channelId.equals("DVB:"+channel.physical())&&c.getSharedPreferences("smarthub",0).getBoolean("own_dvb_ack",false)&&!c.getSharedPreferences("smarthub",0).getBoolean("dvb_tuning",true))return true;Thread.sleep(100);}return false;}
 static void run(Instrumentation test,Context c,Bundle out)throws Exception{
  ReceiverCatalog db=ReceiverCatalog.get(c);db.ensure();need(db.count()>10000,"Real catalogue missing");ReceiverCatalog.Channel a=db.channel(db.uniqueChannel("DUBAI SPORTS 1 HD")),b=db.channel(db.uniqueChannel("DUBAI SPORTS 2 HD"));need(a!=null&&b!=null&&a.ca==0&&b.ca==0&&a.transponder().equals(b.transponder()),"FTA test pair missing");ChannelScope original=ChannelScope.read(c);long group=db.createGroup("Navigation acceptance temporary");Application app=(Application)c.getApplicationContext();test.runOnMainSync(()->app.registerActivityLifecycleCallbacks(life));Activity watching=null;
  try{
   db.member(group,b.id,true);db.member(group,a.id,true);ChannelScope selected=new ChannelScope("",a.satId,0,false,false,group);List<Long> ids=db.navigationIds(selected);need(ids.equals(Arrays.asList(b.id,a.id)),"Favourite group ordinal lost");need(db.adjacent(a,1,selected).id==b.id&&db.adjacent(b,-1,selected).id==a.id,"Favourite group wrap failed");out.putBoolean("favourite_navigation_and_wrap",true);ChannelScope empty=new ChannelScope("unmatched-acceptance-query",a.satId,0,false,false,group);need(db.adjacent(a,1,empty)==null,"Empty scope escaped into other channels");out.putBoolean("empty_list_has_no_random_channel",true);
   ChannelScope radio=new ChannelScope("",a.satId,1,false,false,-1);List<Long> radioIds=db.navigationIds(radio);need(!radioIds.isEmpty(),"Real radio catalogue missing");for(long id:radioIds)need(db.channel(id).tv==1,"TV channel leaked into radio list");out.putInt("nilesat_radio_channels",radioIds.size());out.putBoolean("radio_list_separated",true);
   selected.save(c);c.getSharedPreferences("smarthub",0).edit().putBoolean("own_dvb_ack",false).commit();test.runOnMainSync(()->c.startActivity(new Intent(c,DvbPlaybackActivity.class).putExtra("channel",a.id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));watching=await(DvbPlaybackActivity.class);need(playing(c,a),"Initial real FTA tune failed");long start=SystemClock.elapsedRealtime();key(test,watching,KeyEvent.KEYCODE_CHANNEL_UP);need(playing(c,b),"CH+ did not follow favourite group");out.putLong("channel_up_ms",SystemClock.elapsedRealtime()-start);key(test,watching,KeyEvent.KEYCODE_CHANNEL_DOWN);need(playing(c,a),"CH- did not restore group predecessor");out.putBoolean("physical_ch_up_down",true);
   key(test,watching,KeyEvent.KEYCODE_CHANNEL_UP);Thread.sleep(30);key(test,watching,KeyEvent.KEYCODE_CHANNEL_UP);ReceiverPlayback engine=(ReceiverPlayback)field(watching,DvbPlaybackActivity.class,"player");boolean finalChannel=false;for(int n=0;n<200;n++){Thread.sleep(100);ReceiverCatalog.Channel current=(ReceiverCatalog.Channel)field(engine,ReceiverPlayback.class,"current");boolean busy=(Boolean)field(engine,ReceiverPlayback.class,"loading");if(current!=null&&current.id==a.id&&!busy&&SatelliteState.read(c).channelId.equals("DVB:"+a.physical())){finalChannel=true;break;}}need(finalChannel,"Rapid second channel choice was discarded");out.putBoolean("rapid_zap_last_selection_wins",true);
   key(test,watching,KeyEvent.KEYCODE_DPAD_CENTER);Activity library=await(ReceiverLibraryActivity.class);boolean focused=false;for(int n=0;n<60;n++){Thread.sleep(100);boolean[] check={false};test.runOnMainSync(()->{try{ListView list=(ListView)field(library,ReceiverLibraryActivity.class,"list");EditText query=(EditText)field(library,ReceiverLibraryActivity.class,"query");List<ReceiverCatalog.Channel> rows=(List<ReceiverCatalog.Channel>)field(library,ReceiverLibraryActivity.class,"shown");int p=list.getSelectedItemPosition();check[0]=list.hasFocus()&&!query.hasFocus()&&p>=0&&rows.get(p).id==a.id;}catch(Exception failure){throw new RuntimeException(failure);}});if(check[0]){focused=true;break;}}need(focused,"OK list did not focus the active channel");out.putBoolean("ok_opens_list_on_current_channel",true);test.runOnMainSync(()->{try{EditText q=(EditText)field(library,ReceiverLibraryActivity.class,"query");q.requestFocus();library.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_F));library.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_F));need(q.getText().toString().equals("f"),"Legacy FAV key prevented typing F in search");q.setText("");((ListView)field(library,ReceiverLibraryActivity.class,"list")).requestFocus();}catch(Exception e){throw new RuntimeException(e);}});out.putBoolean("search_f_key_for_text",true);ReceiverSignalReading before=DvbTuner.read();key(test,library,237);Thread.sleep(350);need(DvbTuner.read().tp==before.tp,"Opening SAT unexpectedly retuned hardware");out.putBoolean("sat_key_opens_without_tuning",true);test.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);Thread.sleep(200);key(test,library,KeyEvent.KEYCODE_TV_RADIO_SERVICE);for(int n=0;n<40;n++){Thread.sleep(100);if((Integer)field(library,ReceiverLibraryActivity.class,"type")==1)break;}need((Integer)field(library,ReceiverLibraryActivity.class,"type")==1,"TV/Radio key did not change list type");out.putBoolean("physical_tv_radio_key",true);test.runOnMainSync(library::finish);watching=await(DvbPlaybackActivity.class);
   ReceiverCatalog.Channel station=null;for(long id:radioIds){ReceiverCatalog.Channel ch=db.channel(id);if(ch.ca==0&&ch.audio().length()>0){station=ch;break;}}if(station!=null){ReceiverCatalog.Channel target=station;test.runOnMainSync(()->engine.play(target));boolean accepted=playing(c,target);out.putString("radio_station",target.name);out.putBoolean("radio_decoder_request_accepted",accepted);need(accepted,"Hardware rejected audio-only radio request");}
   test.runOnMainSync(()->engine.play(a));need(playing(c,a),"Could not restore TV after radio");Thread.sleep(2500);DecoderDimensions size=DecoderDimensions.read();out.putBoolean("television_restored_after_radio",size!=null&&size.height==1080);need(out.getBoolean("television_restored_after_radio"),"TV decoder dimensions not restored");long ghost=db.createGroup("Deleted navigation test group");db.deleteGroup(ghost);new ChannelScope("",999999,0,false,false,ghost).save(c);test.runOnMainSync(()->c.startActivity(new Intent(c,ReceiverChannelsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));Activity recovered=await(ReceiverLibraryActivity.class);boolean recoveredRows=false;for(int n=0;n<80;n++){Thread.sleep(100);if(((List<?>)field(recovered,ReceiverLibraryActivity.class,"shown")).size()>8){recoveredRows=true;break;}}need(recoveredRows&&(Long)field(recovered,ReceiverLibraryActivity.class,"group")==-1L&&(Long)field(recovered,ReceiverLibraryActivity.class,"satellite")==-1L,"Deleted group/satellite left an empty channel list");out.putBoolean("deleted_group_recovers_channel_list",true);test.runOnMainSync(()->{try{((ListView)field(recovered,ReceiverLibraryActivity.class,"list")).setSelection(0);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);key(test,recovered,KeyEvent.KEYCODE_CHANNEL_UP);Thread.sleep(200);int[] page={-1};test.runOnMainSync(()->{try{page[0]=((ListView)field(recovered,ReceiverLibraryActivity.class,"list")).getSelectedItemPosition();}catch(Exception e){throw new RuntimeException(e);}});need(page[0]==8,"List CH key did not page eight visible rows");out.putBoolean("channel_keys_page_eight_rows",true);test.runOnMainSync(recovered::finish);await(DvbPlaybackActivity.class);selected.save(c);SatelliteState state=SatelliteState.read(c);new SatelliteGuideRepository(c).record(state);if(!state.title.isEmpty()){Map<String,SatelliteGuideRepository.Event> events=new SatelliteGuideRepository(c).currentChannels(Collections.singleton(state.channelId),System.currentTimeMillis());out.putBoolean("list_epg_uses_real_timed_cache",events.containsKey(state.channelId));}
   ManufacturerFeatures.Entry motor=ManufacturerFeatures.find(c,"motor");out.putBoolean("firmware_motor_route_available",motor!=null&&ManufacturerFeatures.unavailable(c,motor).isEmpty());if(motor!=null)need(motor.intent.getIntExtra("sub_host_type",-1)==1&&motor.intent.getIntExtra("enter_type",-1)==33,"Motor navigation extras do not match OEM contract");out.putBoolean("motor_commands_not_sent_by_test",true);out.putString("cs_agent_playback","NO_PUBLIC_AUTHORIZATION_CONTRACT");out.putString("biss_storage","FIRMWARE_PATCH_UI_ONLY");
  }finally{db.deleteGroup(group);c.getSharedPreferences("smarthub",0).edit().putString("receiver_scope",new ChannelScope("",a.satId,0,false,false,-1).json()).commit();test.runOnMainSync(()->app.unregisterActivityLifecycleCallbacks(life));}
 }
}
